package com.automationstudio.engine.karate.worker;
import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class KarateWorkerMainTest {@TempDir Path temp;
 @Test void performsFoundationHandshakeAndShutdown()throws Exception{UUID id=UUID.randomUUID();byte[] source="Feature: inert".getBytes();var input=new ByteArrayOutputStream();send(input,WorkerProtocol.Message.of("HELLO",id));send(input,new WorkerProtocol.Message("SOURCE",id,Map.of("path","features/a.feature","size",String.valueOf(source.length),"digest",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(source)),"content",Base64.getEncoder().encodeToString(source))));send(input,WorkerProtocol.Message.of("COMPLETE",id));send(input,WorkerProtocol.Message.of("SHUTDOWN",id));var output=new ByteArrayOutputStream();KarateWorkerMain.run(new ByteArrayInputStream(input.toByteArray()),output,temp.resolve("source"));var in=new ByteArrayInputStream(output.toByteArray());assertEquals("READY",WorkerProtocol.read(in,1_048_576).type());assertEquals("ACCEPTED_SOURCE",WorkerProtocol.read(in,1_048_576).type());assertEquals("COMPLETED_FOUNDATION_PROOF",WorkerProtocol.read(in,1_048_576).type());assertEquals("BYE",WorkerProtocol.read(in,1_048_576).type());assertFalse(Files.exists(temp.resolve("source")));}
 @Test void rejectsUnknownMessageCorrelationMismatchAndUnexpectedEof()throws Exception{UUID id=UUID.randomUUID();assertThrows(WorkerProtocol.ProtocolException.class,()->run(List.of(new WorkerProtocol.Message("UNKNOWN",id,Map.of()))));assertThrows(WorkerProtocol.ProtocolException.class,()->run(List.of(WorkerProtocol.Message.of("HELLO",id),WorkerProtocol.Message.of("COMPLETE",UUID.randomUUID()))));assertThrows(WorkerProtocol.ProtocolException.class,()->KarateWorkerMain.run(new ByteArrayInputStream(new byte[0]),new ByteArrayOutputStream(),temp.resolve("eof")));}
 private void run(List<WorkerProtocol.Message> messages)throws Exception{var in=new ByteArrayOutputStream();for(var m:messages)send(in,m);KarateWorkerMain.run(new ByteArrayInputStream(in.toByteArray()),new ByteArrayOutputStream(),temp.resolve(UUID.randomUUID().toString()));}private static void send(OutputStream out,WorkerProtocol.Message m)throws Exception{WorkerProtocol.write(out,m,1_048_576);}
}
